    returns a string encrypted with the alphabet being rotated. 
    The alphabet should be rotated in a manner such that the letters 
    shift down by two multiplied to two places.
    For example:
    encrypt('hi') returns 'lm'
    encrypt('asdfghjkl') returns 'ewhjklnop'
    encrypt('gf') returns 'kj'
    encrypt('et') returns 'ix'
    """
    def rotate_char(c):
        if 'a' <= c <= 'z':
            base = ord('a')
            return chr((ord(c) - base + 4) % 26 + base)
        elif 'A' <= c <= 'Z':
            base = ord('A')
            return chr((ord(c) - base + 4) % 26 + base)
        else:
            return c

    return ''.join(rotate_char(c) for c in s)

def reverse_delete(s, c):
    # Remove all characters in s that are present in c
    result = ''.join(char for char in s if char not in c)

    # Check if the result string is a palindrome
    is_palindrome = result == result[::-1]

    return (result, is_palindrome)

def get_closest_vowel(word):
    vowels = set("aeiouAEIOU")
    n = len(word)

    # Iterate from the second last character down to the second character
    # to ensure the vowel is between two consonants (not at start or end)
    for i in range(n - 2, 0, -1):
        if word[i] in vowels:
            # Check if both neighbors are not vowels (i.e., consonants)
            if word[i - 1] not in vowels and word[i + 1] not in vowels:
                return word[i]

    return ""

